     * ObjectUtils.toString(() -> null, () -> expensive())         = result of expensive()
     * ObjectUtils.toString(() -> "", () -> expensive())           = ""
     * ObjectUtils.toString(() -> "bat", () -> expensive())        = "bat"
     * ObjectUtils.toString(() -> Boolean.TRUE, () -> expensive()) = "true"
